    SELECT (SELECT id FROM `site` WHERE `code` = 'DEMO_SERVICE_03'), (SELECT id FROM device WHERE site_id=(SELECT id FROM `site` WHERE `code` = 'DEMO_SERVICE_03') AND code='ESS_01'), (SELECT id FROM device_point WHERE device_id=(SELECT id FROM device WHERE site_id=(SELECT id FROM `site` WHERE `code` = 'DEMO_SERVICE_03') AND code='ESS_01') AND code='online'), 'sim-full-v1-20261016-alarm-5', TIMESTAMPADD(MINUTE,-120,v_seed_time), NULL, NULL, NULL, 'ACTIVE', 'MAJOR', '【模拟】模拟采集断流，离线两小时', NULL, CAST('{"source": "SIMULATED", "batch": "sim-full-v1-20261016", "value": 0, "threshold": null, "pointCode": "online"}' AS JSON) FROM DUAL
